-- 2026-10-24c: MP Background timelines for the 10 pilot MPs (owner's approval, 24 Oct 2026, "approve background plan").
-- Sets background_timeline (99 entries in all, copied exactly from the pilot data file, which is not committed) and
-- background_last_checked = 2026-10-24 for member_ids 4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309, each only WHERE member_id = <id>. Every entry
-- passed lib/background-timeline.ts validate() before this was written. Nothing else changes.
-- The 10 rows' previous values are kept in public.mp_biography_background_backup_20261024c (readable by service_role
-- only). The guard below fails unless exactly 10 rows change and every other row's background_timeline stays NULL.
-- Undo: 2026-10-24c-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $$ BEGIN
  IF to_regclass('public.mp_biography_background_backup_20261024c') IS NOT NULL THEN RAISE EXCEPTION 'backup table already exists'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309)) <> 10 THEN RAISE EXCEPTION 'expected 10 biography rows for the pilot MPs'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND (background_timeline IS NOT NULL OR background_last_checked IS NOT NULL)) THEN
    RAISE EXCEPTION 'a pilot MP already has a timeline or check date';
  END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'some row already has a timeline'; END IF;
END $$;

-- Backup of the 10 rows' current values (expected NULL), readable by service_role only.
CREATE TABLE public.mp_biography_background_backup_20261024c AS
SELECT member_id, background_timeline, background_last_checked, now() AS backed_up_at
  FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309);
REVOKE ALL ON public.mp_biography_background_backup_20261024c FROM PUBLIC, anon, authenticated;
ALTER TABLE public.mp_biography_background_backup_20261024c ENABLE ROW LEVEL SECURITY;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h FROM public.mp_biography b WHERE member_id NOT IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309);

