DO $$
DECLARE
  set_rows integer;
  others_changed integer;
BEGIN
  SELECT count(*) INTO set_rows FROM public.mp_biography
   WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309) AND jsonb_typeof(background_timeline) = 'array' AND background_last_checked = DATE '2026-10-24';
  IF set_rows <> 10 THEN RAISE EXCEPTION 'expected 10 pilot rows set, got %', set_rows; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 10 THEN RAISE EXCEPTION 'a row outside the pilot has a timeline'; END IF;
  SELECT count(*) INTO others_changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  IF others_changed <> 0 THEN RAISE EXCEPTION '% rows outside the pilot changed', others_changed; END IF;
  IF (SELECT sum(jsonb_array_length(background_timeline)) FROM public.mp_biography WHERE member_id IN (4483, 1427, 5091, 4356, 400, 5449, 5068, 5145, 5284, 5309)) <> 99 THEN RAISE EXCEPTION 'entry total is not 99'; END IF;
  IF has_table_privilege('anon', 'public.mp_biography_background_backup_20261024c', 'SELECT')
     OR has_table_privilege('authenticated', 'public.mp_biography_background_backup_20261024c', 'SELECT') THEN RAISE EXCEPTION 'the backup is readable'; END IF;
END $$;

COMMIT;
